99	
100	OpenSSLTLSContext::OpenSSLTLSContext(TLSSessionSide side, TLSVersion minVer)
101	    : sslCtx_(nullptr), side_(side), verifyPeer_(true)
102	{
103	  sslCtx_ = SSL_CTX_new(SSLv23_method());
104	  if (sslCtx_) {
105	    good_ = true;
106	  }
107	  else {
108	    good_ = false;
109	    A2_LOG_ERROR(fmt("SSL_CTX_new() failed. Cause: %s",
110	                     ERR_error_string(ERR_get_error(), nullptr)));
111	    return;
112	  }
113	
114	  long ver_opts = 0;
115	  switch (minVer) {
116	#ifdef TLS1_3_VERSION
117	  case TLS_PROTO_TLS13:
118	    ver_opts |= SSL_OP_NO_TLSv1_2;
119	    // fall through
120	#endif // TLS1_3_VERSION
121	  case TLS_PROTO_TLS12:
122	    ver_opts |= SSL_OP_NO_TLSv1_1;
123	  // fall through
124	  case TLS_PROTO_TLS11:
125	    ver_opts |= SSL_OP_NO_TLSv1;
126	    ver_opts |= SSL_OP_NO_SSLv3;
127	    break;
128	  default:
129	    assert(0);
130	    abort();
131	  };
132	
133	  // Disable SSLv2 and enable all workarounds for buggy servers
134	  SSL_CTX_set_options(sslCtx_, SSL_OP_ALL | SSL_OP_NO_SSLv2 | ver_opts
135	#ifdef SSL_OP_SINGLE_ECDH_USE
136	                                   | SSL_OP_SINGLE_ECDH_USE
137	#endif // SSL_OP_SINGLE_ECDH_USE
138	#ifdef SSL_OP_NO_COMPRESSION
139	                                   | SSL_OP_NO_COMPRESSION
140	#endif // SSL_OP_NO_COMPRESSION
141	  );
142	  SSL_CTX_set_mode(sslCtx_, SSL_MODE_AUTO_RETRY);
143	  SSL_CTX_set_mode(sslCtx_, SSL_MODE_ENABLE_PARTIAL_WRITE);
144	#ifdef SSL_MODE_RELEASE_BUFFERS
145	  /* keep memory usage low */
146	  SSL_CTX_set_mode(sslCtx_, SSL_MODE_RELEASE_BUFFERS);
147	#endif
148	  if (SSL_CTX_set_cipher_list(sslCtx_, "HIGH:!aNULL:!eNULL") == 0) {
149	    good_ = false;
150	    A2_LOG_ERROR(fmt("SSL_CTX_set_cipher_list() failed. Cause: %s",
151	                     ERR_error_string(ERR_get_error(), nullptr)));
152	  }
153	
154	#if OPENSSL_VERSION_NUMBER < 0x30000000L &&                                    \
155	    OPENSSL_VERSION_NUMBER >= 0x0090800fL
156	#  ifndef OPENSSL_NO_ECDH
157	  auto ecdh = EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);
158	  if (ecdh == nullptr) {
159	    A2_LOG_WARN(fmt("Failed to enable ECDHE cipher suites. Cause: %s",
160	                    ERR_error_string(ERR_get_error(), nullptr)));
161	  }
162	  else {
163	    SSL_CTX_set_tmp_ecdh(sslCtx_, ecdh);
164	    EC_KEY_free(ecdh);
165	  }
166	#  endif // OPENSSL_NO_ECDH
167	#endif   // OPENSSL_VERSION_NUMBER < 0x30000000L && OPENSSL_VERSION_NUMBER >=
168	         // 0x0090800fL
169	}
