87	    return addP12CredentialFile(certfile);
88	  }
89	  int ret = gnutls_certificate_set_x509_key_file(
90	      certCred_, certfile.c_str(), keyfile.c_str(), GNUTLS_X509_FMT_PEM);
91	  if (ret == GNUTLS_E_SUCCESS) {
92	    A2_LOG_INFO(
93	        fmt("Credential files(cert=%s, key=%s) were successfully added.",
94	            certfile.c_str(), keyfile.c_str()));
