107	  BufferedFile(p12file.c_str(), BufferedFile::READ).transfer(ss);
108	  auto datastr = ss.str();
109	  const gnutls_datum_t data = {(unsigned char*)datastr.c_str(),
110	                               (unsigned int)datastr.length()};
111	  int err = gnutls_certificate_set_x509_simple_pkcs12_mem(
112	      certCred_, &data, GNUTLS_X509_FMT_DER, "");
113	  if (err != GNUTLS_E_SUCCESS) {
114	    if (side_ == TLS_SERVER) {
