276	bool OpenSSLTLSContext::addSystemTrustedCACerts()
277	{
278	  if (SSL_CTX_set_default_verify_paths(sslCtx_) != 1) {
279	    A2_LOG_INFO(fmt(MSG_LOADING_SYSTEM_TRUSTED_CA_CERTS_FAILED,
280	                    ERR_error_string(ERR_get_error(), nullptr)));
281	    return false;
282	  }
283	  else {
284	    A2_LOG_INFO("System trusted CA certificates were successfully added.");
285	    return true;
286	  }
287	}
