290	{
291	  if (SSL_CTX_load_verify_locations(sslCtx_, certfile.c_str(), nullptr) != 1) {
292	    A2_LOG_ERROR(fmt(MSG_LOADING_TRUSTED_CA_CERT_FAILED, certfile.c_str(),
293	                     ERR_error_string(ERR_get_error(), nullptr)));
294	    return false;
295	  }
296	  else {
297	    A2_LOG_INFO("Trusted CA certificates were successfully added.");
298	    return true;
299	  }
300	}
