63	template <typename T> class CFRef {
64	  T ref_;
65	
66	public:
67	  CFRef() : ref_(nullptr) {}
68	
69	  CFRef(T ref) : ref_(ref) {}
70	
71	  ~CFRef() { reset(nullptr); }
72	
73	  void reset(T ref)
74	  {
75	    if (ref_) {
76	      CFRelease(ref_);
77	    }
78	    ref_ = ref;
79	  }
