48	#ifndef SP_PROT_TLS1_1_CLIENT
49	#  define SP_PROT_TLS1_1_CLIENT 0x00000200
50	#endif
51	#ifndef SP_PROT_TLS1_1_SERVER
52	#  define SP_PROT_TLS1_1_SERVER 0x00000100
53	#endif
54	#ifndef SP_PROT_TLS1_2_CLIENT
55	#  define SP_PROT_TLS1_2_CLIENT 0x00000800
56	#endif
57	#ifndef SP_PROT_TLS1_2_SERVER
58	#  define SP_PROT_TLS1_2_SERVER 0x00000400
59	#endif
60	
61	#ifndef SCH_USE_STRONG_CRYPTO
62	#  define SCH_USE_STRONG_CRYPTO 0x00400000
63	#endif
64	
65	#define WEAK_CIPHER_BITS 56
66	#define STRONG_CIPHER_BITS 128
67	
68	namespace aria2 {
69	
70	WinTLSContext::WinTLSContext(TLSSessionSide side, TLSVersion ver)
71	    : side_(side), store_(0)
72	{
73	  memset(&credentials_, 0, sizeof(credentials_));
74	  credentials_.dwVersion = SCHANNEL_CRED_VERSION;
75	  credentials_.grbitEnabledProtocols = 0;
76	  if (side_ == TLS_CLIENT) {
77	    switch (ver) {
78	    case TLS_PROTO_TLS11:
79	      credentials_.grbitEnabledProtocols |= SP_PROT_TLS1_1_CLIENT;
80	    // fall through
81	    case TLS_PROTO_TLS12:
82	      credentials_.grbitEnabledProtocols |= SP_PROT_TLS1_2_CLIENT;
83	      break;
84	    default:
85	      assert(0);
86	      abort();
87	    }
88	  }
89	  else {
90	    switch (ver) {
91	    case TLS_PROTO_TLS11:
92	      credentials_.grbitEnabledProtocols |= SP_PROT_TLS1_1_SERVER;
93	    // fall through
94	    case TLS_PROTO_TLS12:
95	      credentials_.grbitEnabledProtocols |= SP_PROT_TLS1_2_SERVER;
96	      break;
97	    default:
98	      assert(0);
99	      abort();
100	    }
101	  }
102	
103	  // Strong protocol versions: Use a minimum strength, which might be later
104	  // refined using SCH_USE_STRONG_CRYPTO in the flags.
105	  credentials_.dwMinimumCipherStrength = STRONG_CIPHER_BITS;
106	
107	  setVerifyPeer(side_ == TLS_CLIENT);
108	}
109	
110	TLSContext* TLSContext::make(TLSSessionSide side, TLSVersion ver)
111	{
112	  return new WinTLSContext(side, ver);
113	}
114	
115	WinTLSContext::~WinTLSContext()
116	{
117	  if (store_) {
118	    ::CertCloseStore(store_, 0);
119	    store_ = 0;
120	  }
121	}
122	
123	bool WinTLSContext::getVerifyPeer() const
124	{
125	  return credentials_.dwFlags & SCH_CRED_AUTO_CRED_VALIDATION;
126	}
127	
128	void WinTLSContext::setVerifyPeer(bool verify)
129	{
130	  cred_.reset();
131	
132	  // Never automatically push any client or server certs. We'll do cert setup
133	  // ourselves.
134	  credentials_.dwFlags = SCH_CRED_NO_DEFAULT_CREDS;
135	
136	  if (credentials_.dwMinimumCipherStrength > WEAK_CIPHER_BITS) {
137	    // Enable strong crypto if we already set a minimum cipher streams.
138	    // This might actually require even stronger algorithms, which is a good
139	    // thing.
140	    credentials_.dwFlags |= SCH_USE_STRONG_CRYPTO;
141	  }
142	
143	  if (side_ != TLS_CLIENT || !verify) {
144	    // No verification for servers and if user explicitly requested it
145	    credentials_.dwFlags |=
146	        SCH_CRED_MANUAL_CRED_VALIDATION | SCH_CRED_IGNORE_NO_REVOCATION_CHECK |
147	        SCH_CRED_IGNORE_REVOCATION_OFFLINE | SCH_CRED_NO_SERVERNAME_CHECK;
148	    return;
149	  }
150	
151	  // Verify other side's cert chain.
152	  credentials_.dwFlags |= SCH_CRED_AUTO_CRED_VALIDATION |
153	                          SCH_CRED_REVOCATION_CHECK_CHAIN |
154	                          SCH_CRED_IGNORE_NO_REVOCATION_CHECK;
155	}
156	
157	CredHandle* WinTLSContext::getCredHandle()
158	{
159	  if (cred_) {
160	    return cred_.get();
161	  }
162	
163	  TimeStamp ts;
164	  cred_.reset(new CredHandle());
165	
166	  const CERT_CONTEXT* ctx = nullptr;
167	  if (store_) {
168	    ctx = ::CertEnumCertificatesInStore(store_, nullptr);
169	    if (!ctx) {
170	      throw DL_ABORT_EX("Failed to load certificate");
171	    }
172	    credentials_.cCreds = 1;
173	    credentials_.paCred = &ctx;
174	  }
175	  else {
176	    credentials_.cCreds = 0;
177	    credentials_.paCred = nullptr;
178	  }
179	  SECURITY_STATUS status = ::AcquireCredentialsHandleW(
180	      nullptr, (SEC_WCHAR*)UNISP_NAME_W,
181	      side_ == TLS_CLIENT ? SECPKG_CRED_OUTBOUND : SECPKG_CRED_INBOUND, nullptr,
182	      &credentials_, nullptr, nullptr, cred_.get(), &ts);
183	  if (ctx) {
184	    ::CertFreeCertificateContext(ctx);
185	  }
186	  if (status != SEC_E_OK) {
187	    cred_.reset();
188	    throw DL_ABORT_EX("Failed to initialize WinTLS context handle");
189	  }
190	  return cred_.get();
191	}
192	
193	bool WinTLSContext::addCredentialFile(const std::string& certfile,
194	                                      const std::string& keyfile)
195	{
196	  std::stringstream ss;
197	  BufferedFile(certfile.c_str(), "rb").transfer(ss);
198	  auto data = ss.str();
199	  CRYPT_DATA_BLOB blob = {(DWORD)data.length(), (BYTE*)data.c_str()};
200	  if (!::PFXIsPFXBlob(&blob)) {
201	    A2_LOG_ERROR("Not a valid PKCS12 file");
202	    return false;
203	  }
204	  HCERTSTORE store =
205	      ::PFXImportCertStore(&blob, L"", CRYPT_EXPORTABLE | CRYPT_USER_KEYSET);
206	  if (!store_) {
207	    store = ::PFXImportCertStore(&blob, nullptr,
208	                                 CRYPT_EXPORTABLE | CRYPT_USER_KEYSET);
209	  }
210	  if (!store) {
211	    A2_LOG_ERROR("Failed to import PKCS12 store");
212	    return false;
213	  }
214	  auto ctx = ::CertEnumCertificatesInStore(store, nullptr);
215	  if (!ctx) {
216	    A2_LOG_ERROR("PKCS12 file does not contain certificates");
217	    ::CertCloseStore(store, 0);
218	    return false;
219	  }
220	  ::CertFreeCertificateContext(ctx);
221	
222	  if (store_) {
223	    ::CertCloseStore(store_, 0);
224	  }
225	  store_ = store;
226	  cred_.reset();
227	
228	  return true;
229	}
