101	struct hash_validator {
102	  const std::string& hash_;
103	
104	  hash_validator(const std::string& hash) : hash_(hash) {}
105	
106	  inline bool operator()(std::string type) const
107	  {
108	    return MessageDigest::isValidHash(type, hash_);
109	  }
110	};
111	
112	struct hash_finder {
113	  CFDataRef data_;
114	  const std::string& hash_;
115	
116	  hash_finder(CFDataRef data, const std::string& hash)
117	      : data_(data), hash_(hash)
118	  {
119	  }
120	
121	  inline bool operator()(std::string type) const
122	  {
123	    std::string hash =
124	        MessageDigest::create(type)
125	            ->update(CFDataGetBytePtr(data_), CFDataGetLength(data_))
126	            .digest();
127	    hash = util::toHex(hash);
128	    return hash == hash_;
129	  }
130	};
