132	std::string errToString(OSStatus err)
133	{
134	  std::string rv = "Unknown error";
135	  CFRef<CFStringRef> cerr(SecCopyErrorMessageString(err, nullptr));
136	  if (!cerr) {
137	    return rv;
138	  }
139	  size_t len = CFStringGetLength(cerr.get()) * 4;
140	  auto buf = make_unique<char[]>(len);
141	  if (CFStringGetCString(cerr.get(), buf.get(), len, kCFStringEncodingUTF8)) {
142	    rv = buf.get();
143	  }
144	  return rv;
145	}
