317	bool AppleTLSContext::tryAsPKCS12(const std::string& certfile)
318	{
319	#if defined(__MAC_10_6)
320	  std::stringstream ss;
321	  BufferedFile(certfile.c_str(), BufferedFile::READ).transfer(ss);
322	  auto data = ss.str();
323	  if (data.empty()) {
324	    A2_LOG_ERROR("Couldn't read certificate file.");
325	    return false;
326	  }
327	  CFRef<CFDataRef> dataRef(
328	      CFDataCreate(nullptr, (const UInt8*)data.c_str(), data.size()));
329	  if (!dataRef) {
330	    A2_LOG_ERROR("Couldn't allocate PKCS12 data");
331	    return false;
332	  }
333	
334	  return tryAsPKCS12(dataRef.get(), "") || tryAsPKCS12(dataRef.get(), nullptr);
335	
336	#else // defined(__MAC_10_6)
337	  A2_LOG_INFO("PKCS12 files are only supported in OSX 10.6 or later.");
338	  return false;
339	
340	#endif // defined(__MAC_10_6)
341	}
342	
343	bool AppleTLSContext::tryAsPKCS12(CFDataRef data, const char* password)
344	{
345	#if defined(__MAC_10_6)
346	  CFRef<CFStringRef> passwordRef;
347	  if (password) {
348	    passwordRef.reset(CFStringCreateWithBytes(nullptr, (const UInt8*)password,
349	                                              strlen(password),
350	                                              kCFStringEncodingUTF8, false));
351	  }
352	  const void* keys[] = {kSecImportExportPassphrase};
353	  const void* values[] = {passwordRef.get()};
354	  CFRef<CFDictionaryRef> options(
355	      CFDictionaryCreate(nullptr, keys, values, 1, nullptr, nullptr));
356	  if (!options) {
357	    A2_LOG_ERROR("Failed to create options");
358	    return false;
359	  }
360	
361	  CFRef<CFArrayRef> items;
362	  CFArrayRef raw_items = nullptr;
363	  OSStatus rv = SecPKCS12Import(data, options.get(), &raw_items);
364	  if (rv != errSecSuccess) {
365	    A2_LOG_DEBUG(
366	        fmt("Failed to parse PKCS12 data: %s", errToString(rv).c_str()));
367	    return false;
368	  }
369	  items.reset(raw_items);
370	
371	  CFDictionaryRef idAndTrust =
372	      (CFDictionaryRef)CFArrayGetValueAtIndex(items.get(), 0);
373	  if (!idAndTrust) {
374	    A2_LOG_ERROR("Failed to get identity and trust from PKCS12 data");
375	    return false;
376	  }
377	  credentials_ =
378	      (SecIdentityRef)CFDictionaryGetValue(idAndTrust, kSecImportItemIdentity);
379	  if (!credentials_) {
380	    A2_LOG_ERROR("Failed to get credentials PKCS12 data");
381	    return false;
382	  }
383	  CFRetain(credentials_);
384	  A2_LOG_INFO("Loaded certificate from file");
385	  return true;
386	
387	#else // defined(__MAC_10_6)
388	  return false;
389	
390	#endif // defined(__MAC_10_6)
391	}
