      handshakeErr = "";
      if (status & GNUTLS_CERT_INVALID) {
        handshakeErr += " `not signed by known authorities or invalid'";
      }
      if (status & GNUTLS_CERT_REVOKED) {
        handshakeErr += " `revoked by its CA'";
