      }
      if (status & GNUTLS_CERT_EXPIRED) {
        handshakeErr += " `expired'";
      }
      if (status & GNUTLS_CERT_PURPOSE_MISMATCH) {
        handshakeErr += " `unsuitable certificate purpose`";
      }
