87	// enabled and non-blocking socket is used.  To workaround this bug,
88	// for these versions of GnuTLS, we disable OCSP status extension. We
89	// expect that upcoming (at the time of this writing) 3.1.19 and 3.2.9
90	// will fix this bug.  See
91	// http://lists.gnutls.org/pipermail/gnutls-devel/2014-January/006679.html
92	// for details.
93	#if (GNUTLS_VERSION_NUMBER >= 0x030103 &&                                      \
94	     GNUTLS_VERSION_NUMBER <= 0x030112) ||                                     \
95	    (GNUTLS_VERSION_NUMBER >= 0x030200 && GNUTLS_VERSION_NUMBER <= 0x030208)
