125	      return TLS_ERR_ERROR;
126	    }
127	  }
128	#endif // A2_DISABLE_OCSP
129	
130	  // It seems err is not error message, but the argument string
131	  // which causes syntax error.
132	  const char* err;
133	#ifdef USE_GNUTLS_SYSTEM_CRYPTO_POLICY
